function renderDoctorReport(findings, skillCount) {
  if (findings.length === 0)
    return `Checked ${skillCount} skill(s). Nothing to report.`;
  const lines = [];
  for (const severity of ["broken", "smell"]) {
    const group = findings.filter((finding) => finding.severity === severity);
    if (group.length === 0)
      continue;
    lines.push(severity === "broken" ? `
BROKEN (${group.length}) - these waste an agent's turn` : `
WORTH A LOOK (${group.length}) - these may be correct as they stand`);
    const bySkill = new Map;
    for (const finding of group)
      bySkill.set(finding.skill, [...bySkill.get(finding.skill) ?? [], finding]);
    for (const [skill, entries] of [...bySkill].sort(([left], [right]) => left.localeCompare(right))) {
      lines.push(`  ${skill}`);
      for (const entry of entries)
        lines.push(`    ${entry.detail}`);
    }
  }
  const broken = findings.filter((finding) => finding.severity === "broken").length;
  lines.push(`
Checked ${skillCount} skill(s): ${broken} broken, ${findings.length - broken} worth a look.`);
  return lines.join(`
`);
}
